TASK:{"title":"SWEN3204 Software Architecture – Assignment 2: Short-Answer Questions","overview":"Answer six short questions applying architecture concepts to the CampusEats scenario. The assignment is worth 40 marks, including 4 marks for communication. Submit an individual, single-document response."}
RUBRIC:[{"id":"C1","name":"Q1 Quality attributes","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Two attributes that clearly matter most are chosen and justified from the scenario. Both scenarios have all six parts and both response measures are measurable."},{"label":"Proficient","min":3,"max":4,"desc":"Suitable attributes are chosen with some justification. Scenarios are mostly complete but one is missing a part or has a response measure that is not measurable."},{"label":"Developing","min":1,"max":2,"desc":"Attributes are named with little or no justification, or the scenarios are not in six-part form or are not measurable."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or irrelevant."}]},{"id":"C2","name":"Q2 Architectural style","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"A clear recommendation justified by at least two trade-offs that are specific to the scenario (team size, load profile, known problems). The downside of the recommendation is acknowledged."},{"label":"Proficient","min":3,"max":4,"desc":"A clear recommendation with two trade-offs, but one is generic or not linked to the scenario, or no downside is acknowledged."},{"label":"Developing","min":1,"max":2,"desc":"A recommendation with only one trade-off, or with generic textbook advantages and disadvantages only."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no recommendation."}]},{"id":"C3","name":"Q3 Availability calculation","weight":null,"max":8,"levels":[{"label":"Excellent","min":7,"max":8,"desc":"Parts (a), (b) and (c) are all correct with working shown, to the requested precision."},{"label":"Proficient","min":5,"max":6,"desc":"The method is correct throughout but there is one arithmetic or rounding slip, or exactly one part is incorrect."},{"label":"Developing","min":1,"max":4,"desc":"The series calculation is attempted but two or more parts are incorrect, or working is not shown."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or no correct element."}]},{"id":"C4","name":"Q4 Resilience pattern","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"An appropriate pattern is named, its mechanism is explained correctly, it is applied to the outage, and at least one drawback or tuning consideration is given."},{"label":"Proficient","min":3,"max":4,"desc":"An appropriate pattern is named and explained correctly, but it is only loosely applied to the outage or no drawback or tuning consideration is given."},{"label":"Developing","min":1,"max":2,"desc":"A pattern is named but the explanation is incorrect or very thin."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted or an unsuitable pattern."}]},{"id":"C5","name":"Q5 Consistency and availability","weight":null,"max":6,"levels":[{"label":"Excellent","min":5,"max":6,"desc":"Both choices are justified, the CAP theorem is used correctly, and a suitable concrete technique is named for each case."},{"label":"Proficient","min":3,"max":4,"desc":"Both choices are reasonable and techniques are named, but the CAP theorem is explained incorrectly or imprecisely, or one technique is missing."},{"label":"Developing","min":1,"max":2,"desc":"Choices are stated with little justification, or the CAP theorem is not used."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C6","name":"Q6 Architecture decision record","weight":null,"max":5,"levels":[{"label":"Excellent","min":5,"max":5,"desc":"Context, Decision and Consequences are all present and specific to the scenario, with at least one positive and one negative consequence."},{"label":"Proficient","min":3,"max":4,"desc":"All three sections are present but the consequences are one-sided (no negative consequence) or the context is generic."},{"label":"Developing","min":1,"max":2,"desc":"One or more sections are missing or the record does not describe a decision."},{"label":"Missing","min":0,"max":0,"desc":"Not attempted."}]},{"id":"C7","name":"Communication and format","weight":null,"max":4,"levels":[{"label":"Excellent","min":4,"max":4,"desc":"Every answer is within 150 words, terminology is precise, the required headings are used and sources are cited in IEEE style."},{"label":"Proficient","min":3,"max":3,"desc":"Clear writing, but one answer exceeds the word limit or there are minor citation or formatting problems."},{"label":"Developing","min":1,"max":2,"desc":"Several answers exceed the word limit, or the writing is hard to follow, or sources are not cited."},{"label":"Missing","min":0,"max":0,"desc":"Format requirements ignored."}]}]
MARKING:{"requirements":[{"id":"R1","met":"partial","where":"Question 1"},{"id":"R2","met":"yes","where":"Question 2"},{"id":"R3","met":"partial","where":"Question 3(c)"},{"id":"R4","met":"yes","where":"Question 4"},{"id":"R5","met":"yes","where":"Question 5"},{"id":"R6","met":"partial","where":"Question 6"},{"id":"R7","met":"yes","where":"References"}],"technical_issues":[{"where":"Question 3(c)","issue":"End-to-end availability after adding the second provider is not recomputed: 0.9995 × 0.999 × 0.9995 × 0.999975 = 0.99798 (99.80%), so monthly downtime is ~1.5 hours, not 0.018 hours. The 99.9975% figure is only the payment component."},{"where":"Question 3","issue":"(a) reports 99.30% (99.301%) and (b) 5.0 hours, both acceptable, but the 0.02% rounding is not carried through to the two-decimal requirement in (c)."},{"where":"Question 1","issue":"Availability response measure 'stay up most of the time' is not measurable, and the response (browse menus) does not match the order-service artefact."},{"where":"Question 5","issue":"CAP misuse: partition tolerance cannot be traded away in a network partition; the choice is between consistency and availability during the partition."},{"where":"Question 6","issue":"No negative consequence recorded in the ADR, so the record is one-sided."},{"where":"Question 2","issue":"Answer is approximately 195 words, over the 150-word limit."}],"overall":"Strong, scenario-grounded answers with a sound style recommendation and good resilience reasoning. Main losses: Q3(c) never recomputes end-to-end availability, Q5 misstates CAP, Q6 lacks a negative consequence, Q2 exceeds the word limit and Q1's availability measure is unmeasurable. Total 31/40.","criteria":[{"id":"C1","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Both attributes are well chosen and justified from the scenario data (900 orders, 4.2 s p95). The performance scenario has all six parts and a measurable measure. The availability scenario has all six parts but its response measure ('stay up most of the time') is not measurable, and the response drifts from the order-placement artefact.","evidence":[{"where":"Question 1","quote":"The two most important quality attributes are performance and availability, because the business depends on the lunch hour"},{"where":"Question 1","quote":"Response measure: the system should stay up most of the time."}]},{"id":"C2","level":"Excellent","mark":6.0,"scale":6.0,"points":6.0,"max":6.0,"reasoning":"A clear, argued recommendation (modular monolith) with two scenario-specific trade-offs: team size versus operational overhead, and the observation that the known problems stem from a single VM and the deployment process rather than the monolith shape. A specific downside is explicitly acknowledged.","evidence":[{"where":"Question 2","quote":"With five developers, running eight or ten services would mean more time spent on infrastructure than on features."},{"where":"Question 2","quote":"The trade-off I accept is that modules cannot be scaled independently, and a bug in one module can still crash the whole process."}]},{"id":"C3","level":"Proficient","mark":5.0,"scale":8.0,"points":5.0,"max":8.0,"reasoning":"(a) 0.99301 = 99.30% and (b) 5.0 hours are correct with working shown. In (c) the payment combination 0.999975 is right, but it is never recombined with the other three components: the end-to-end availability should be 99.80% and downtime about 1.5 hours, not 99.9975% and 0.018 hours.","evidence":[{"where":"Question 3(c)","quote":"the new availability of placing an order is 99.9975%, which reduces the downtime to 0.000025 × 720 = 0.018 hours"}]},{"id":"C4","level":"Excellent","mark":5.0,"scale":5.0,"points":5.0,"max":5.0,"reasoning":"Circuit breaker is named and its Closed/Open/Half-Open mechanism, including failure counting and timeouts, is explained correctly. It is applied concretely to the 25-minute outage with a user-visible fallback, and a tuning consideration (failure threshold and window) is provided.","evidence":[{"where":"Question 4","quote":"When failures exceed a threshold (for example 50% of calls in 10 seconds) the breaker moves to Open"},{"where":"Question 4","quote":"Students would have seen \"payment temporarily unavailable, please try again or pay at the counter\" instead of the whole app hanging for 25 minutes."}]},{"id":"C5","level":"Proficient","mark":4.0,"scale":6.0,"points":4.0,"max":6.0,"reasoning":"Both choices are sensible and justified, with concrete techniques (Redis cache with TTL; idempotency keys). However, the CAP explanation is wrong: a partition-tolerant distributed system cannot 'give up' partition tolerance and keep both C and A; it must sacrifice one during a partition.","evidence":[{"where":"Question 5","quote":"for payments we choose consistency and availability and give up partition tolerance"},{"where":"Question 5","quote":"it is better to show a slightly stale menu from a cache (for example Redis with a 60-second TTL)"}]},{"id":"C6","level":"Proficient","mark":4.0,"scale":5.0,"points":4.0,"max":5.0,"reasoning":"Context, Decision and Consequences are all present and specific (offline tablet, synchronous call, 4.2 s p95, RabbitMQ, retrying worker). Consequences are entirely positive; no negative consequence such as duplicate notifications, eventual consistency for outlets, or queue operations burden is stated.","evidence":[{"where":"Question 6","quote":"Placing an order no longer waits for the outlet, so the response time improves."}]},{"id":"C7","level":"Proficient","mark":3.0,"scale":4.0,"points":3.0,"max":4.0,"reasoning":"Writing is clear and precise, headings and IEEE-style references with a reference list are present; Q1 (~145), Q4, Q5 and Q6 appear within 150 words. Q2 is roughly 195 words, exceeding the limit.","evidence":[{"where":"Question 2","quote":"The 20-minute weekly downtime is a deployment process problem and can be removed with rolling deployments."}]}]}
